def command(repo, args, env=None):
    cp=subprocess.run(args,cwd=repo,text=True,capture_output=True,env=env)
    if cp.returncode:
        raise RuntimeError('Command failed: '+ ' '.join(args)+'\n'+cp.stdout+cp.stderr)
    return cp.stdout.strip()

def git(repo,*args): return command(repo,['git',*args])
def load(path): return json.loads(path.read_text(encoding='utf-8'))
def dump(path,value): path.write_text(json.dumps(value,indent=2,sort_keys=True)+'\n',encoding='utf-8')
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()

def clean(repo):
    # Only an untracked installer is allowed; never discard an operator's changes.
    for row in git(repo,'status','--porcelain','--untracked-files=all').splitlines():
        if row.startswith('?? ') and row[3:] in INSTALL_FILES: continue
        raise RuntimeError('Repository has uncommitted changes: '+row)

def repository(repo):
    repo=Path(git(repo,'rev-parse','--show-toplevel')).resolve()
    origin=git(repo,'config','--get','remote.origin.url')
    normalized=origin.lower().removesuffix('.git').rstrip('/')
    if normalized not in {'https://github.com/morfindien/bubbleverse-model','git@github.com:morfindien/bubbleverse-model','ssh://git@github.com/morfindien/bubbleverse-model'}:
        raise RuntimeError('Installation target must be Morfindien/bubbleverse-model; source repository writes are forbidden.')
    clean(repo)
    if git(repo,'branch','--show-current')!='main':
        raise RuntimeError('Select the model repository main branch before installation.')
    return repo

def payload():
    try: patch=zlib.decompress(base64.b64decode(PATCH_ZLIB_BASE64))
    except Exception as exc: raise RuntimeError('Embedded patch payload is corrupt') from exc
    if hashlib.sha256(patch).hexdigest()!=PATCH_SHA256:
        raise RuntimeError('Embedded patch hash mismatch; no files changed.')
    return patch

def fingerprints(repo):
    return {p.relative_to(repo).as_posix():sha(p)
            for base in ['accepted','versions/accepted','model','candidate','evidence']
            for p in (repo/base).rglob('*') if p.is_file()}

def snapshot(repo):
    for frozen in (repo/'versions/accepted/v0.4').iterdir():
        if not frozen.is_file():continue
        name=frozen.name
        if name=='TEST_RESULT.json': live=repo/'tests/results/Q042_MODEL_UPDATE_TEST_RESULT.json'
        elif name=='evidence_registry.json':live=repo/'evidence/evidence_registry.json'
        elif name=='q_update.json':live=repo/'evidence/q_updates/Q042.json'
        elif (repo/'accepted'/name).exists():live=repo/'accepted'/name
        else:live=repo/'model'/name
        if frozen.read_bytes()!=live.read_bytes():raise RuntimeError('Snapshot mismatch: '+name)
    prov=load(repo/'candidate/Q042_PROVENANCE.json')
    for rel,expected in prov['protected_input_hashes'].items():
        if rel.startswith('versions/') and sha(repo/rel)!=expected:
            raise RuntimeError('Previous snapshot changed: '+rel)
    for source in prov['source_files']:
        if sha(repo/'evidence/sources/Q042'/source['archived_name'])!=source['sha256']:
            raise RuntimeError('Original source hash mismatch: '+source['archived_name'])

def validate(repo,work):
    before=fingerprints(repo)
    for script,args in [('test_q042_campaign_guard.py',[]),('q042_model_validate.py',[]),('model_campaign.py',['validate'])]:
        command(repo,[sys.executable,str(repo/'tests/programs'/script),*args])
        print('PASS '+script)
    workflow=(repo/'.github/workflows/00-bubbleverse-model-start-public.yml').read_text()
    match=re.search(r"(?m)^([ ]*)python - <<'PY'\n(.*?)^\1PY\s*$",workflow,re.S)
    if not match:raise RuntimeError('Cannot safely extract the existing public healthcheck.')
    engine=work/'public_healthcheck.py';engine.write_text(textwrap.dedent(match.group(2)))
    command(repo,[sys.executable,str(engine)],env={**os.environ,'BV_OPERATION':'test','BV_INPUT':''})
    result=load(repo/'run-output/result.json')
    if not result.get('all_green') or result.get('tests_passed')!=20:raise RuntimeError('Public healthcheck failed.')
    if before!=fingerprints(repo):raise RuntimeError('A test modified scientific state.')
    snapshot(repo)
    print('PASS public healthcheck 20/20; scientific files unchanged')
    return {'Q042':'11/11 PASS','formal':'13/13 PASS','regression':'11/11 PASS','integration':'4/4 PASS','public_healthcheck':'20/20 PASS','non_destructive':True}

def commit(repo,message):
    git(repo,'-c','user.name=Bubbleverse Q042 Installer','-c','user.email=q042-installer@users.noreply.github.com','commit','--quiet','-m',message)
    return git(repo,'rev-parse','HEAD')

def record_publication(repo):
    state=load(repo/'accepted/model_state.json')
    if state.get('current_q')!='Q042' or state.get('accepted_model_version')!='v0.4':
        raise RuntimeError('A validated local Q042 installation is required first.')
    head=git(repo,'rev-parse','HEAD')
    remote=git(repo,'ls-remote','origin','refs/heads/main').split()
    if not remote or remote[0]!=head:
        raise RuntimeError('Remote main does not match this local commit; publication cannot be verified.')
    release=load(repo/'release/MODEL_RELEASE_HANDOFF.json')
    if release.get('remote_promotion_verified'):
        print('PUBLICATION_ALREADY_VERIFIED');return
    snapshot(repo)
    if git(repo,'branch','--show-current')!='main' or git(repo,'rev-parse','HEAD')!=head:
        raise RuntimeError('Operator branch moved during publication verification; no receipt applied.')
    receipt=load(repo/'release/Q042_INSTALLATION_RESULT.json')
    release.update(remote_promotion_verified=True,repository_write_gate='PASS_VERIFIED_OPERATOR_PUBLICATION',verified_remote_publication_commit=head)
    receipt.update(remote_promotion_verified=True,verified_remote_publication_commit=head,verified_at=datetime.now(timezone.utc).isoformat())
    dump(repo/'release/MODEL_RELEASE_HANDOFF.json',release)
    dump(repo/'release/Q042_INSTALLATION_RESULT.json',receipt)
    git(repo,'add','release/MODEL_RELEASE_HANDOFF.json','release/Q042_INSTALLATION_RESULT.json')
    final=commit(repo,'Record verified operator publication of Q042 model')
    print('PUBLICATION_VERIFIED '+head+'; local receipt commit '+final)

def install(repo,check=False):
    patch=payload() # Verify the complete payload before creating or changing files.
    state=load(repo/'accepted/model_state.json')
    if state.get('current_q')=='Q042' and state.get('accepted_model_version')=='v0.4':
        input_head=git(repo,'rev-parse','HEAD')
        with tempfile.TemporaryDirectory(prefix='q042-healthcheck-') as folder:
            work=Path(folder);stage=work/'validated-model'
            git(repo,'worktree','add','--quiet','--detach',str(stage),input_head)
            try:validate(stage,work)
            finally:git(repo,'worktree','remove','--force',str(stage))
        if git(repo,'branch','--show-current')!='main' or git(repo,'rev-parse','HEAD')!=input_head:
            raise RuntimeError('Operator branch moved during current-state validation.')
        print('ALREADY_CURRENT — no new commit or version');return
    if state.get('current_q')!='Q041' or state.get('accepted_model_version')!='v0.3':
        raise RuntimeError('Required accepted input is Q041/v0.3; no scientific state is skipped.')
    git(repo,'merge-base','--is-ancestor',BASE,'HEAD')
    changed=set(git(repo,'diff','--name-only',BASE,'HEAD').splitlines())-INSTALL_FILES
    if changed:raise RuntimeError('Model files changed since the validated base: '+', '.join(sorted(changed)))
    input_head=git(repo,'rev-parse','HEAD')
    with tempfile.TemporaryDirectory(prefix='q042-install-') as folder:
        work=Path(folder);stage=work/'validated-model';patchfile=work/'Q042.patch';patchfile.write_bytes(patch)
        git(repo,'worktree','add','--quiet','--detach',str(stage),input_head)
        try:
            git(stage,'apply','--check','--index',str(patchfile));git(stage,'apply','--index',str(patchfile))
            # The reviewed tree may additionally contain the two operator-uploaded installers.
            index=Path(git(stage,'rev-parse','--git-path','index'))
            if not index.is_absolute():index=stage/index
            copy_index=work/'reviewed.index';shutil.copyfile(index,copy_index)
            env={**os.environ,'GIT_INDEX_FILE':str(copy_index)}
            command(stage,['git','update-index','--force-remove','--',*sorted(INSTALL_FILES)],env=env)
            reviewed_tree=command(stage,['git','write-tree'],env=env)
            if reviewed_tree!=EXPECTED_TREE:raise RuntimeError('Installed tree differs from the reviewed transaction.')
            tests=validate(stage,work)
            if check:print('CHECK_PASS — original model and branch unchanged');return
            promotion=commit(stage,'Promote validated Q042 evidence-only model v0.4')
            release=load(stage/'release/MODEL_RELEASE_HANDOFF.json')
            release.update(projection_only=False,promotion_commit=promotion,
                promotion_commit_semantics='Actual reachable local scientific promotion commit; remote publication has a separate verification receipt',
                repository_write_gate='LOCAL_PROMOTION_READY_FOR_OPERATOR_PUSH',remote_promotion_verified=False)
            candidate=load(stage/'candidate/candidate_state.json')
            candidate.update(promotion_commit=promotion,promotion_commit_semantics='Actual reachable local promotion commit')
            dump(stage/'release/MODEL_RELEASE_HANDOFF.json',release);dump(stage/'candidate/candidate_state.json',candidate)
            receipt={'schema_version':1,'target_q':'Q042','accepted_version':'v0.4','revision':'R000004',
                'installation_input_commit':input_head,'scientific_input_commit':BASE,'promotion_commit':promotion,
                'patch_sha256':PATCH_SHA256,'tests':tests,'remote_promotion_verified':False,
                'source_repository_modified':False,'production_restart_authorized':False,
                'new_scientific_q_allocated':False,'installed_at':datetime.now(timezone.utc).isoformat()}
            dump(stage/'release/Q042_INSTALLATION_RESULT.json',receipt)
            git(stage,'add','release/MODEL_RELEASE_HANDOFF.json','candidate/candidate_state.json','release/Q042_INSTALLATION_RESULT.json')
            final=commit(stage,'Record Q042 local promotion and operator installation receipt')
            validate(stage,work)
            clean(repo)
            if git(repo,'branch','--show-current')!='main':raise RuntimeError('Operator branch changed during validation; no installation applied.')
            if git(repo,'rev-parse','HEAD')!=input_head:raise RuntimeError('Operator branch moved during validation; no installation applied.')
            git(repo,'merge','--ff-only',final)
            print('INSTALLED_LOCAL Q042/v0.4 — '+final)
            print('No push was performed. The operator may now publish: git push origin HEAD:main')
        finally:
            # Only the installer-owned temporary validation worktree is removed.
            git(repo,'worktree','remove','--force',str(stage))

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo',type=Path,default=Path.cwd())
    group=parser.add_mutually_exclusive_group();group.add_argument('--check',action='store_true');group.add_argument('--record-publication',action='store_true')
    args=parser.parse_args()
    try:
        repo=repository(args.repo)
        if args.record_publication:record_publication(repo)
        else:install(repo,args.check)
        return 0
    except Exception as exc:
        print('INSTALLATION_BLOCKED: '+str(exc),file=sys.stderr);return 1
if __name__=='__main__':raise SystemExit(main())
